"""EPIC protocol laboratory: replay, audit, and export operations.

Reads UTF-8 JSON Lines requests from stdin and writes exactly one JSON
object per input line.  Standard library only; fully iterative algorithms.
"""

import sys
import json
import re

LINE_MAX = 32 * 1024 * 1024
NINE = 1000000000
BIG = 1 << 60
INF = float('inf')
MAX_PENDING = 2048
MAX_CREATED = 200000

KIND_NAMES = ('up', 'uack', 'down', 'dack')


class JsonErr(Exception):
    pass


class SchemaErr(Exception):
    pass


class LimitErr(Exception):
    pass


NAME_RE = re.compile(r'\A[A-Za-z][A-Za-z0-9_]{0,63}\Z')

REPLAY_KEYS = frozenset(('op', 'inputs', 'slots', 'window', 'events'))
GRAPH_KEYS = frozenset(('op', 'inputs', 'states', 'edges', 'start', 'fairness'))


def _pairs_hook(pairs):
    d = dict(pairs)
    if len(d) != len(pairs):
        raise JsonErr()
    return d


def _bad_const(_s):
    raise JsonErr()


def _parse_float(s):
    try:
        f = float(s)
    except ValueError:
        raise JsonErr()
    if f != f or f == INF or f == -INF:
        raise JsonErr()
    return f


def check_name(s):
    if NAME_RE.match(s) is not None:
        return
    if len(s) > 64:
        raise LimitErr()
    raise SchemaErr()


# --------------------------------------------------------------------------
# request dispatch and validation
# --------------------------------------------------------------------------

def handle(obj):
    if type(obj) is not dict:
        raise SchemaErr()
    op = obj.get('op')
    if type(op) is not str:
        raise SchemaErr()
    if op == 'replay':
        if frozenset(obj) != REPLAY_KEYS:
            raise SchemaErr()
    elif op == 'audit' or op == 'export':
        if frozenset(obj) != GRAPH_KEYS:
            raise SchemaErr()
    else:
        raise SchemaErr()
    P, R, D, inp = validate_inputs(obj['inputs'])
    if op == 'replay':
        return do_replay(obj, P, R, D, inp)
    return do_graph(obj, op, P, R, D, inp)


def validate_inputs(v):
    """Validate the P x R x D rank-major rectangular integer array."""
    if type(v) is not list:
        raise SchemaErr()
    P = len(v)
    if P < 1 or P > 8:
        raise LimitErr()
    for row in v:
        if type(row) is not list:
            raise SchemaErr()
    R = len(v[0])
    if R > 128:
        raise LimitErr()
    for row in v:
        if len(row) != R:
            raise SchemaErr()
    if R == 0:
        return P, 0, 0, v
    first = v[0][0]
    if type(first) is not list:
        raise SchemaErr()
    D = len(first)
    if D > 32:
        raise LimitErr()
    for row in v:
        for vec in row:
            if type(vec) is not list:
                raise SchemaErr()
            w = len(vec)
            if w != D:
                if w > 32:
                    raise LimitErr()
                raise SchemaErr()
            for x in vec:
                if type(x) is not int:
                    raise SchemaErr()
                if x < -NINE or x > NINE:
                    raise LimitErr()
    return P, R, D, v


# --------------------------------------------------------------------------
# replay
# --------------------------------------------------------------------------

def do_replay(obj, P, R, D, inp):
    slots_n = obj['slots']
    if type(slots_n) is not int:
        raise SchemaErr()
    if slots_n < 1 or slots_n > 16:
        raise LimitErr()
    window = obj['window']
    if type(window) is not int:
        raise SchemaErr()
    if window < 1 or window > slots_n:
        raise LimitErr()
    raw_ev = obj['events']
    if type(raw_ev) is not list:
        raise SchemaErr()
    if len(raw_ev) > 20000:
        raise LimitErr()
    events = []
    for e in raw_ev:
        if type(e) is not list:
            raise SchemaErr()
        ne = len(e)
        if ne == 0:
            raise SchemaErr()
        k = e[0]
        if k == 'send':
            if ne != 3:
                raise SchemaErr()
            r = e[1]
            q = e[2]
            if type(r) is not int or type(q) is not int:
                raise SchemaErr()
            if r < 0 or r >= P:
                raise LimitErr()
            if q < 0 or q >= R:
                raise LimitErr()
            events.append((0, r, q))
        elif k == 'retry':
            if ne != 2:
                raise SchemaErr()
            r = e[1]
            if type(r) is not int:
                raise SchemaErr()
            if r < 0 or r >= P:
                raise LimitErr()
            events.append((1, r, 0))
        elif k == 'deliver' or k == 'drop' or k == 'duplicate':
            if ne != 2:
                raise SchemaErr()
            pid = e[1]
            if type(pid) is not int:
                raise SchemaErr()
            if pid < 0 or pid > 200000:
                raise LimitErr()
            if k == 'deliver':
                events.append((2, pid, 0))
            elif k == 'drop':
                events.append((3, pid, 0))
            else:
                events.append((4, pid, 0))
        else:
            raise SchemaErr()
    return run_replay(P, R, D, inp, slots_n, window, events)


def run_replay(P, R, D, inp, slots_n, window, events):
    sent = [0] * P
    received = [[] for _ in range(P)]
    up_next = [0] * P
    acked = [0] * P
    floor = 0
    buf = {}          # absolute seq q -> [ranks set, sum list]
    pending = {}      # id -> (kind, rank, seq, value)
    next_id = 0
    ev_out = []

    for (ek, a, b) in events:
        created = []
        status = 'ok'
        if ek == 0:                                    # send
            r = a
            q = b
            enabled = False
            if sent[r] <= q:
                lim = sent[r] + window
                if lim > R:
                    lim = R
                if q < lim:
                    enabled = True
            if enabled:
                pending[next_id] = (0, r, q, inp[r][q])
                created.append(next_id)
                next_id += 1
            else:
                status = 'disabled'
        elif ek == 1:                                  # retry
            r = a
            thr = acked[r]
            if buf:
                for q in sorted(buf):
                    ent = buf[q]
                    if q >= thr and len(ent[0]) == P:
                        pending[next_id] = (2, r, q, ent[1])
                        created.append(next_id)
                        next_id += 1
        else:
            pid = a
            pkt = pending.pop(pid, None)
            if pkt is None:
                status = 'missing'
            else:
                k2, r2, s2, v2 = pkt
                if ek == 3:                           # drop
                    pass
                elif ek == 4:                         # duplicate
                    pending[pid] = pkt
                    pending[next_id] = (k2, r2, s2, v2)
                    created.append(next_id)
                    next_id += 1
                else:                                 # deliver
                    if k2 == 0:                       # up
                        q = s2
                        if floor <= q < floor + slots_n:
                            ent = buf.get(q)
                            if ent is None:
                                ranks = set((r2, ))
                                s = list(v2)
                                buf[q] = (ranks, s)
                                full = (P == 1)
                            else:
                                ranks, s = ent
                                if r2 in ranks:
                                    full = False
                                else:
                                    ranks.add(r2)
                                    for i in range(D):
                                        s[i] += v2[i]
                                    full = (len(ranks) == P)
                            k3 = up_next[r2]
                            while True:
                                e3 = buf.get(k3)
                                if e3 is None or r2 not in e3[0]:
                                    break
                                k3 += 1
                            up_next[r2] = k3
                            pending[next_id] = (1, r2, k3, None)
                            created.append(next_id)
                            next_id += 1
                            if full:
                                for rr in range(P):
                                    pending[next_id] = (2, rr, q, s)
                                    created.append(next_id)
                                    next_id += 1
                        else:
                            pending[next_id] = (1, r2, up_next[r2], None)
                            created.append(next_id)
                            next_id += 1
                    elif k2 == 1:                     # uack
                        if sent[r2] < s2:
                            sent[r2] = s2
                    elif k2 == 2:                     # down
                        row = received[r2]
                        if s2 == len(row):
                            row.append(v2)
                        pending[next_id] = (3, r2, len(row), None)
                        created.append(next_id)
                        next_id += 1
                    else:                             # dack
                        if acked[r2] < s2:
                            acked[r2] = s2
                        fl = min(acked)
                        if fl > floor:
                            floor = fl
                            if buf:
                                for q in [q for q in buf if q < floor]:
                                    del buf[q]
        if len(pending) > MAX_PENDING or next_id > MAX_CREATED:
            raise LimitErr()
        ev_out.append({'status': status, 'created': created})

    hosts = []
    for r in range(P):
        hosts.append({'sent': sent[r], 'received': received[r]})
    slot_out = []
    for q in sorted(buf):
        ranks, s = buf[q]
        slot_out.append({'seq': q, 'ranks': sorted(ranks), 'sum': s})
    pk_out = []
    for pid in sorted(pending):
        k2, r2, s2, v2 = pending[pid]
        pk_out.append({'id': pid, 'kind': KIND_NAMES[k2], 'rank': r2,
                       'seq': s2, 'value': v2})
    return {'hosts': hosts, 'floor': floor, 'slots': slot_out,
            'packets': pk_out, 'events': ev_out}


# --------------------------------------------------------------------------
# audit / export: shared graph request validation
# --------------------------------------------------------------------------

def do_graph(obj, op, P, R, D, inp):
    raw_states = obj['states']
    if type(raw_states) is not list:
        raise SchemaErr()
    n = len(raw_states)
    if n < 1 or n > 12000:
        raise LimitErr()

    # exact AllReduce sums per sequence
    exp = []
    if R > 0:
        for q in range(R):
            s = list(inp[0][q])
            for r in range(1, P):
                vr = inp[r][q]
                s = [a + b for a, b in zip(s, vr)]
            exp.append(s)

    slot_cache = {}
    safe_flags = bytearray(n)
    done_flags = bytearray(n)

    for si in range(n):
        st = raw_states[si]
        if type(st) is not dict:
            raise SchemaErr()
        if len(st) != 2:
            raise SchemaErr()
        if 'delivered' not in st or 'slots' not in st:
            raise SchemaErr()
        dv = st['delivered']
        sl = st['slots']
        if type(dv) is not list or type(sl) is not list:
            raise SchemaErr()
        if len(dv) > 8:
            raise LimitErr()
        if len(dv) != P:
            raise SchemaErr()
        if len(sl) > 16:
            raise LimitErr()
        is_safe = True
        is_done = True
        for row in dv:
            if type(row) is not list:
                raise SchemaErr()
            L = len(row)
            if L > R:
                raise LimitErr()
            if L != R:
                is_done = False
            for vec in row:
                if type(vec) is not list:
                    raise SchemaErr()
                w = len(vec)
                if w != D:
                    if w > 32:
                        raise LimitErr()
                    raise SchemaErr()
                for x in vec:
                    if type(x) is not int:
                        raise SchemaErr()
                    if x < -BIG or x > BIG:
                        raise LimitErr()
            if is_safe and L > 0:
                if row != exp[:L]:
                    is_safe = False
        seen_seq = set()
        for slot in sl:
            if type(slot) is not dict:
                raise SchemaErr()
            if len(slot) != 3 or 'seq' not in slot or 'ranks' not in slot \
                    or 'sum' not in slot:
                raise SchemaErr()
            q = slot['seq']
            if type(q) is not int:
                raise SchemaErr()
            if q < 0 or q >= R:
                raise LimitErr()
            if q in seen_seq:
                raise SchemaErr()
            seen_seq.add(q)
            rk = slot['ranks']
            if type(rk) is not list:
                raise SchemaErr()
            rks = set()
            for x in rk:
                if type(x) is not int:
                    raise SchemaErr()
                if x < 0 or x >= P:
                    raise LimitErr()
                if x in rks:
                    raise SchemaErr()
                rks.add(x)
            sm = slot['sum']
            if type(sm) is not list:
                raise SchemaErr()
            w = len(sm)
            if w != D:
                if w > 32:
                    raise LimitErr()
                raise SchemaErr()
            for x in sm:
                if type(x) is not int:
                    raise SchemaErr()
                if x < -BIG or x > BIG:
                    raise LimitErr()
            if is_safe:
                key = (q, tuple(sorted(rks)))
                want = slot_cache.get(key)
                if want is None:
                    if len(rks) == P:
                        want = exp[q]
                    else:
                        acc = None
                        for r in sorted(rks):
                            vr = inp[r][q]
                            if acc is None:
                                acc = list(vr)
                            else:
                                acc = [a + b for a, b in zip(acc, vr)]
                        if acc is None:
                            acc = [0] * D
                        want = acc
                    slot_cache[key] = want
                if sm != want:
                    is_safe = False
        safe_flags[si] = 1 if is_safe else 0
        done_flags[si] = 1 if is_done else 0

    # ---- edges
    raw_edges = obj['edges']
    if type(raw_edges) is not list:
        raise SchemaErr()
    if len(raw_edges) > 60000:
        raise LimitErr()
    edges = []
    by_action = {}
    names = set()
    seen = set()
    for eid, e in enumerate(raw_edges):
        if type(e) is not list or len(e) != 3:
            raise SchemaErr()
        u = e[0]
        nm = e[1]
        v = e[2]
        if type(u) is not int or type(v) is not int:
            raise SchemaErr()
        if u < 0 or u >= n or v < 0 or v >= n:
            raise LimitErr()
        if type(nm) is not str:
            raise SchemaErr()
        check_name(nm)
        tr = (u, nm, v)
        if tr in seen:
            raise SchemaErr()
        seen.add(tr)
        names.add(nm)
        edges.append(tr)
        lst = by_action.get(nm)
        if lst is None:
            by_action[nm] = lst = []
        lst.append((u, v, eid))

    # ---- start
    start = obj['start']
    if type(start) is not int:
        raise SchemaErr()
    if start < 0 or start >= n:
        raise LimitErr()

    # ---- fairness
    raw_fair = obj['fairness']
    if type(raw_fair) is not list:
        raise SchemaErr()
    if len(raw_fair) > 16:
        raise LimitErr()
    fair = []
    fset = set()
    for f in raw_fair:
        if type(f) is not dict:
            raise SchemaErr()
        if len(f) != 2 or 'action' not in f or 'mode' not in f:
            raise SchemaErr()
        act = f['action']
        mode = f['mode']
        if type(act) is not str:
            raise SchemaErr()
        check_name(act)
        if type(mode) is not str or (mode != 'weak' and mode != 'strong'):
            raise SchemaErr()
        if act in fset:
            raise SchemaErr()
        fset.add(act)
        fair.append((act, mode))
    all_names = names | fset
    if len(all_names) > 64:
        raise LimitErr()

    if op == 'export':
        return build_export(n, start, edges, all_names, fair, safe_flags,
                            done_flags)
    return do_audit(n, start, edges, by_action, fair, safe_flags, done_flags)


# --------------------------------------------------------------------------
# audit computation
# --------------------------------------------------------------------------

def do_audit(n, start, edges, by_action, fair, safe_flags, done_flags):
    # ---- safety: any reachable state (full edge relation) that is unsafe?
    if safe_flags[start] == 0:
        safe = False
        safety = {'prefix': []}
    else:
        adj_all = [[] for _ in range(n)]
        for eid in range(len(edges)):
            u = edges[eid][0]
            adj_all[u].append((edges[eid][2], eid))
        pprev = [-1] * n
        peid = [-1] * n
        visited = bytearray(n)
        visited[start] = 1
        queue = [start]
        qi = 0
        found = -1
        while qi < len(queue):
            u = queue[qi]
            qi += 1
            for (v, eid) in adj_all[u]:
                if not visited[v]:
                    visited[v] = 1
                    pprev[v] = u
                    peid[v] = eid
                    if safe_flags[v] == 0:
                        found = v
                        break
                    queue.append(v)
            if found >= 0:
                break
        if found < 0:
            safe = True
            safety = None
        else:
            safe = False
            path = []
            x = found
            while x != start:
                path.append(peid[x])
                x = pprev[x]
            path.reverse()
            safety = {'prefix': path}

    # ---- liveness: fair termination
    liveness = None
    terminates = True
    if done_flags[start] == 0:
        # adjacency restricted to non-done states
        adjD = [[] for _ in range(n)]
        adjDe = [[] for _ in range(n)]
        radjD = [[] for _ in range(n)]
        radjDe = [[] for _ in range(n)]
        for eid in range(len(edges)):
            u = edges[eid][0]
            v = edges[eid][2]
            if done_flags[u] == 0 and done_flags[v] == 0:
                adjD[u].append(v)
                adjDe[u].append(eid)
                radjD[v].append(u)
                radjDe[v].append(eid)
        depth = [-1] * n
        dprev = [-1] * n
        deid = [-1] * n
        depth[start] = 0
        order = [start]
        qi = 0
        while qi < len(order):
            u = order[qi]
            qi += 1
            av = adjD[u]
            ae = adjDe[u]
            for i in range(len(av)):
                v = av[i]
                if depth[v] < 0:
                    depth[v] = depth[u] + 1
                    dprev[v] = u
                    deid[v] = ae[i]
                    order.append(v)
        if not fair:
            terminates = False
            liveness = {'prefix': [], 'loop': [-1]}
        else:
            k = len(fair)
            en_mask = [0] * n
            for t in range(k):
                bit = 1 << t
                nm = fair[t][0]
                for (u, v, eid) in by_action.get(nm, ()):
                    en_mask[u] |= bit
            active = bytearray(n)
            for s in order:
                active[s] = 1
            chosen = None
            while True:
                comps = compute_sccs(n, adjD, active)
                if not comps:
                    chosen = None
                    break
                comp_of = [-1] * n
                for ci in range(len(comps)):
                    c = comps[ci]
                    for s in c:
                        comp_of[s] = ci
                internal = [0] * len(comps)
                for t in range(k):
                    nm = fair[t][0]
                    bit = 1 << t
                    for (u, v, eid) in by_action.get(nm, ()):
                        cu = comp_of[u]
                        if cu >= 0 and cu == comp_of[v]:
                            internal[cu] |= bit
                kill = bytearray(len(comps))
                rmbits = [0] * len(comps)
                chosen = None
                for ci in range(len(comps)):
                    c = comps[ci]
                    um = 0
                    im = -1
                    for s in c:
                        m = en_mask[s]
                        um |= m
                        im &= m
                    bad_strong = 0
                    for t in range(k):
                        bit = 1 << t
                        if fair[t][1] == 'strong':
                            if (um & bit) and not (internal[ci] & bit):
                                bad_strong |= bit
                        else:
                            if (im & bit) and not (internal[ci] & bit):
                                kill[ci] = 1
                    if bad_strong == 0 and kill[ci] == 0:
                        chosen = (ci, comps[ci], um, im)
                        break
                    rmbits[ci] = bad_strong
                if chosen is not None:
                    break
                for ci in range(len(comps)):
                    if kill[ci]:
                        for s in comps[ci]:
                            active[s] = 0
                    elif rmbits[ci]:
                        rb = rmbits[ci]
                        for s in comps[ci]:
                            if en_mask[s] & rb:
                                active[s] = 0
            if chosen is None:
                terminates = True
            else:
                ci, S, um, im = chosen
                Sset = set(S)
                v0 = S[0]
                dv0 = depth[v0]
                for s in S:
                    if depth[s] < dv0:
                        v0 = s
                        dv0 = depth[s]
                feats = []
                for t in range(k):
                    bit = 1 << t
                    nm, mode = fair[t]
                    if mode == 'strong':
                        need = (um & bit) != 0
                    else:
                        need = (im & bit) != 0
                    if need:
                        for (u, v, eid) in by_action.get(nm, ()):
                            if u in Sset and v in Sset:
                                feats.append(('e', u, eid, v))
                                break
                    else:
                        for s in S:
                            if not (en_mask[s] & bit):
                                feats.append(('n', s))
                                break
                if feats:
                    fprev = [-1] * n
                    feid = [-1] * n
                    fprev[v0] = -2
                    q2 = [v0]
                    qi = 0
                    while qi < len(q2):
                        u = q2[qi]
                        qi += 1
                        av = adjD[u]
                        ae = adjDe[u]
                        for i in range(len(av)):
                            v = av[i]
                            if fprev[v] == -1 and v in Sset:
                                fprev[v] = u
                                feid[v] = ae[i]
                                q2.append(v)
                    bprev = [-1] * n
                    beid = [-1] * n
                    bprev[v0] = -2
                    q2 = [v0]
                    qi = 0
                    while qi < len(q2):
                        u = q2[qi]
                        qi += 1
                        rv = radjD[u]
                        re_ = radjDe[u]
                        for i in range(len(rv)):
                            x = rv[i]
                            if bprev[x] == -1 and x in Sset:
                                bprev[x] = u
                                beid[x] = re_[i]
                                q2.append(x)
                    walk = []
                    for f in feats:
                        if f[0] == 'e':
                            u = f[1]
                            eid = f[2]
                            v = f[3]
                            # v0 -> u
                            seg = []
                            x = u
                            while x != v0:
                                seg.append(feid[x])
                                x = fprev[x]
                            seg.reverse()
                            walk.extend(seg)
                            walk.append(eid)
                            # v -> v0
                            x = v
                            while x != v0:
                                walk.append(beid[x])
                                x = bprev[x]
                        else:
                            x = f[1]
                            seg = []
                            while x != v0:
                                seg.append(feid[x])
                                x = fprev[x]
                            seg.reverse()
                            walk.extend(seg)
                            while x != v0:
                                walk.append(beid[x])
                                x = bprev[x]
                    loop = walk if walk else [-1]
                else:
                    loop = [-1]
                pref = []
                x = v0
                while x != start:
                    pref.append(deid[x])
                    x = dprev[x]
                pref.reverse()
                liveness = {'prefix': pref, 'loop': loop}
                terminates = False

    return {'safe': safe, 'safety': safety, 'terminates': terminates,
            'liveness': liveness}


def compute_sccs(n, adj, active):
    """Iterative Tarjan decomposition of the subgraph induced by active."""
    idx = [-1] * n
    low = [0] * n
    onstk = bytearray(n)
    sstack = []
    comps = []
    cnt = 0
    for root in range(n):
        if not active[root] or idx[root] != -1:
            continue
        idx[root] = low[root] = cnt
        cnt += 1
        sstack.append(root)
        onstk[root] = 1
        fnode = [root]
        fptr = [0]
        while fnode:
            v = fnode[-1]
            av = adj[v]
            la = len(av)
            pi = fptr[-1]
            advanced = False
            while pi < la:
                w = av[pi]
                pi += 1
                if not active[w]:
                    continue
                iw = idx[w]
                if iw == -1:
                    fptr[-1] = pi
                    idx[w] = low[w] = cnt
                    cnt += 1
                    sstack.append(w)
                    onstk[w] = 1
                    fnode.append(w)
                    fptr.append(0)
                    advanced = True
                    break
                elif onstk[w]:
                    if iw < low[v]:
                        low[v] = iw
            if advanced:
                continue
            fnode.pop()
            fptr.pop()
            lv = low[v]
            if fnode:
                p = fnode[-1]
                if lv < low[p]:
                    low[p] = lv
            if lv == idx[v]:
                comp = []
                while True:
                    w = sstack.pop()
                    onstk[w] = 0
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)
    return comps


# --------------------------------------------------------------------------
# TLA+ export
# --------------------------------------------------------------------------

def build_export(n, start, edges, all_names, fair, safe_flags, done_flags):
    anames = sorted(all_names)
    idx = {}
    for i in range(len(anames)):
        idx[anames[i]] = i + 1
    wf = []
    sf = []
    for (act, mode) in fair:
        j = idx[act]
        if mode == 'weak':
            wf.append(j)
        else:
            sf.append(j)
    wf.sort()
    sf.sort()
    lines = []
    lines.append('---- MODULE ModelData ----')
    lines.append('EXTENDS Integers, Sequences, FiniteSets')
    lines.append('Nodes == 0..%d' % (n - 1))
    lines.append('Initial == %d' % start)
    if edges:
        eb = []
        for (u, nm, v) in edges:
            eb.append('<<%d, %d, %d>>' % (u, idx[nm], v))
        lines.append('Edges == {' + ', '.join(eb) + '}')
    else:
        lines.append('Edges == {}')
    if anames:
        lines.append('ActionNames == <<' +
                     ', '.join('"%s"' % x for x in anames) + '>>')
    else:
        lines.append('ActionNames == <<>>')
    lines.append('WFIds == {' + ', '.join(str(x) for x in wf) + '}')
    lines.append('SFIds == {' + ', '.join(str(x) for x in sf) + '}')
    lines.append('SafeNodes == {' +
                 ', '.join(str(i) for i in range(n) if safe_flags[i]) + '}')
    lines.append('DoneNodes == {' +
                 ', '.join(str(i) for i in range(n) if done_flags[i]) + '}')
    lines.append('====')
    module = '\n'.join(lines) + '\n'
    config = ('SPECIFICATION Spec\nINVARIANT Safety\nPROPERTY Termination\n'
              'CHECK_DEADLOCK FALSE\n')
    return {'module': module, 'config': config}


# --------------------------------------------------------------------------
# I/O driver
# --------------------------------------------------------------------------

def process_line(line):
    if len(line) > LINE_MAX:
        return '{"error":"E_LIMIT"}'
    try:
        text = line.decode('utf-8')
    except UnicodeDecodeError:
        return '{"error":"E_JSON"}'
    try:
        obj = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_bad_const, parse_float=_parse_float)
    except JsonErr:
        return '{"error":"E_JSON"}'
    except (ValueError, RecursionError):
        return '{"error":"E_JSON"}'
    try:
        res = handle(obj)
    except LimitErr:
        return '{"error":"E_LIMIT"}'
    except SchemaErr:
        return '{"error":"E_SCHEMA"}'
    except Exception:
        return '{"error":"E_SCHEMA"}'
    try:
        return json.dumps(res)
    except Exception:
        return '{"error":"E_SCHEMA"}'


def main():
    data = sys.stdin.buffer.read()
    out = sys.stdout.write
    pos = 0
    n = len(data)
    while pos < n:
        i = data.find(b'\n', pos)
        if i < 0:
            line = data[pos:]
            pos = n
        else:
            line = data[pos:i]
            pos = i + 1
        out(process_line(line))
        out('\n')
    sys.stdout.flush()


main()
