"""Independent, deliberately literal re-implementation of the replay engine
for cross-checking (written from the spec text, structured differently)."""

def ref_replay(P, R, D, inputs, nslots, window, events):
    # host state
    sent = {r: 0 for r in range(P)}
    received = {r: [] for r in range(P)}
    # switch state
    floor = 0
    up_next = {r: 0 for r in range(P)}
    acked = {r: 0 for r in range(P)}
    # circular buffer: physical index -> None or (tagged seq, ranks set, sum)
    phys = [None] * nslots
    packets = {}   # id -> dict with id,kind,rank,seq,value
    log = []
    nxt = 0
    ok = True
    for ev in events:
        created = []
        status = "ok"
        if ev[0] == "send":
            _, r, q = ev
            lim = min(R, sent[r] + window)
            if sent[r] <= q < lim:
                pk = {"id": nxt, "kind": "up", "rank": r, "seq": q,
                      "value": list(inputs[r][q])}
                packets[nxt] = pk
                nxt += 1
                created.append(pk["id"])
            else:
                status = "disabled"
        elif ev[0] == "retry":
            _, r = ev
            full = sorted([t[0] for t in phys if t is not None and
                           len(t[1]) == P and t[0] >= acked[r]])
            for q in full:
                for t in phys:
                    if t is not None and t[0] == q:
                        pk = {"id": nxt, "kind": "down", "rank": r, "seq": q,
                              "value": list(t[2])}
                        packets[nxt] = pk
                        nxt += 1
                        created.append(pk["id"])
        else:
            _, pid = ev[1], ev[0] and ev[1]
            pid = ev[1]
            if pid not in packets:
                status = "missing"
            else:
                pk = packets[pid]
                if ev[0] == "drop":
                    del packets[pid]
                elif ev[0] == "duplicate":
                    cp = {"id": nxt, "kind": pk["kind"], "rank": pk["rank"],
                          "seq": pk["seq"],
                          "value": list(pk["value"]) if pk["value"] is not None else None}
                    packets[nxt] = cp
                    nxt += 1
                    created.append(cp["id"])
                else:  # deliver
                    del packets[pid]
                    kind, r, seq, val = pk["kind"], pk["rank"], pk["seq"], pk["value"]
                    if kind == "up":
                        if floor <= seq < floor + nslots:
                            p = seq % nslots
                            cur = phys[p]
                            if cur is None or cur[0] != seq:
                                # create fresh entry in this physical slot
                                phys[p] = (seq, {r}, list(val))
                                nf = len({r}) == P
                            else:
                                ranks, s = cur[1], cur[2]
                                if r in ranks:
                                    nf = False
                                else:
                                    ranks.add(r)
                                    s = [a + b for a, b in zip(s, val)]
                                    nf = len(ranks) == P
                            # advance up_next
                            while True:
                                t = phys.get(up_next[r] % nslots) if False else phys[up_next[r] % nslots]
                                if t is not None and t[0] == up_next[r] and r in t[1]:
                                    up_next[r] += 1
                                else:
                                    break
                            pk2 = {"id": nxt, "kind": "uack", "rank": r,
                                   "seq": up_next[r], "value": None}
                            packets[nxt] = pk2
                            nxt += 1
                            created.append(pk2["id"])
                            if nf:
                                t = phys[seq % nslots]
                                for rr in range(P):
                                    pk3 = {"id": nxt, "kind": "down", "rank": rr,
                                           "seq": seq, "value": list(t[2])}
                                    packets[nxt] = pk3
                                    nxt += 1
                                    created.append(pk3["id"])
                        else:
                            pk2 = {"id": nxt, "kind": "uack", "rank": r,
                                   "seq": up_next[r], "value": None}
                            packets[nxt] = pk2
                            nxt += 1
                            created.append(pk2["id"])
                    elif kind == "uack":
                        sent[r] = max(sent[r], seq)
                    elif kind == "down":
                        if seq == len(received[r]):
                            received[r].append(val)
                        pk2 = {"id": nxt, "kind": "dack", "rank": r,
                               "seq": len(received[r]), "value": None}
                        packets[nxt] = pk2
                        nxt += 1
                        created.append(pk2["id"])
                    else:  # dack
                        acked[r] = max(acked[r], seq)
                        floor = min(acked.values())
                        for i in range(nslots):
                            t = phys[i]
                            if t is not None and t[0] < floor:
                                phys[i] = None
        if len(packets) > 2048 or nxt > 200000:
            raise RuntimeError("LIMIT")
        log.append({"status": status, "created": created})
    slots_out = []
    for t in sorted([t for t in phys if t is not None]):
        slots_out.append({"seq": t[0], "ranks": sorted(t[1]), "sum": list(t[2])})
    pk_out = [{"id": i, "kind": packets[i]["kind"], "rank": packets[i]["rank"],
               "seq": packets[i]["seq"],
               "value": None if packets[i]["value"] is None else list(packets[i]["value"])}
              for i in sorted(packets)]
    hosts = [{"sent": sent[r], "received": [list(v) for v in received[r]]} for r in range(P)]
    return {"hosts": hosts, "floor": floor, "slots": slots_out,
            "packets": pk_out, "events": log}
