"""Ground truth for audit by exhaustive enumeration on tiny graphs."""
import itertools

def build(P, R, D, inputs, states, edges, start, fair):
    n = len(states)
    exp = []
    for q in range(R):
        s = list(inputs[0][q])
        for r in range(1, P):
            s = [a + b for a, b in zip(s, inputs[r][q])]
        exp.append(s)
    safe = []
    done = []
    for st in states:
        sf = True; dn = True
        dv = st["delivered"]
        for r in range(len(dv)):
            row = dv[r]
            if len(row) != R: dn = False
            for qi in range(len(row)):
                if row[qi] != exp[qi]: sf = False
        for slot in st["slots"]:
            rk = slot["ranks"]; q = slot["seq"]
            acc = [0]*D
            for x in sorted(set(rk)):
                for i in range(D): acc[i] += inputs[x][q][i]
            if slot["sum"] != acc: sf = False
        safe.append(sf); done.append(dn)
    allt = {}
    for eid, (u, nm, v) in enumerate(edges):
        allt.setdefault(nm, []).append((u, v, eid))
    en = [set() for _ in range(n)]
    for nm, lst in allt.items():
        for (u, v, eid) in lst: en[u].add(nm)
    return safe, done, allt, en

def brute_truth(P, R, D, inputs, states, edges, start, fair):
    n = len(states)
    safe, done, allt, en = build(P, R, D, inputs, states, edges, start, fair)
    # safety: any unsafe state reachable from start via all edges?
    reach = set([start]); stack = [start]
    adj = {}
    for (u, nm, v) in edges: adj.setdefault(u, []).append(v)
    while stack:
        u = stack.pop()
        for v in adj.get(u, []):
            if v not in reach: reach.add(v); stack.append(v)
    safe_res = all(safe[s] for s in reach)
    # liveness
    if done[start]:
        return safe_res, True
    # nondone set
    ND = set([s for s in range(n) if not done[s]])
    RD = set([start])
    stack = [start]
    adjD = {}
    for (u, nm, v) in edges:
        if not done[u] and not done[v]: adjD.setdefault(u, []).append(v)
    while stack:
        u = stack.pop()
        for v in adjD.get(u, []):
            if v not in RD: RD.add(v); stack.append(v)
    if not RD:
        return safe_res, True
    best = None
    for sz in range(1, len(ND) + 1):
        for sub in itertools.combinations(sorted(ND), sz):
            Vp = set(sub)
            if not (Vp & RD): continue
            # mutual reachability inside Vp
            if len(Vp) > 1:
                ok = True
                for a in Vp:
                    seen = set([a]); st2 = [a]
                    while st2:
                        x = st2.pop()
                        for y in adjD.get(x, []):
                            if y in Vp and y not in seen:
                                seen.add(y); st2.append(y)
                    if seen != Vp: ok = False; break
                if not ok: continue
            # fairness conditions
            good = True
            for (a, mode) in fair:
                enset = [x for x in Vp if a in en[x]]
                has_edge_internal = any(u in Vp and v in Vp
                                        for (u, v, eid) in allt.get(a, []))
                if mode == "strong":
                    if enset and not has_edge_internal: good = False; break
                else:
                    if len(enset) == len(Vp) and not has_edge_internal: good = False; break
            if good:
                best = Vp; break
        if best: break
    return safe_res, (best is None)
PYEOF
