"""Independent structural validation of audit responses."""

def validate(P, R, D, inputs, states, edges, start, fair, resp):
    n = len(states)
    safe, done, allt, en = __import__("brute").build(P, R, D, inputs, states, edges, start, fair)
    errs = []
    assert resp.keys() == set(["safe", "safety", "terminates", "liveness"]), resp.keys()
    # check safe/safety consistency
    if resp["safe"]:
        if resp["safety"] is not None: errs.append("safety not null though safe")
    else:
        w = resp["safety"]
        assert isinstance(w, dict) and w.keys() == {"prefix"}
        # walk the prefix
        cur = start
        for eid in w["prefix"]:
            if not (0 <= eid < len(edges)): errs.append("bad safety edge id"); break
            if edges[eid][0] != cur: errs.append("safety walk mismatch at %d" % eid); break
            cur = edges[eid][2]
        else:
            if not safe[cur] is False and safe[cur]:
                errs.append("safety endpoint is safe")
        # if safe is False, then an unsafe state must indeed be reachable
    # check terminates/liveness
    if resp["terminates"]:
        if resp["liveness"] is not None: errs.append("liveness not null though terminating")
    else:
        w = resp["liveness"]
        assert isinstance(w, dict) and w.keys() == {"prefix", "loop"}, w
        assert isinstance(w["loop"], list) and len(w["loop"]) >= 1
        cur = start
        for eid in w["prefix"]:
            if not (0 <= eid < len(edges)): errs.append("bad prefix edge id"); break
            if edges[eid][0] != cur: errs.append("prefix walk mismatch at %d" % eid); break
            cur = edges[eid][2]
            if done[cur]: errs.append("prefix visits done state")
        else:
            for eid in w["loop"]:
                if eid == -1:
                    pass
                elif not (0 <= eid < len(edges)):
                    errs.append("bad loop edge id"); break
                elif edges[eid][0] != cur:
                    errs.append("loop walk mismatch at %d" % eid); break
                else:
                    cur = edges[eid][2]
            else:
                v0 = start
                # recompute endpoint of prefix
                e2 = start
                for eid in w["prefix"]:
                    e2 = edges[eid][2]
                if cur != e2: errs.append("loop does not close at prefix endpoint")
                # states visited by the loop
                st = e2
                loopstates = [st]
                for eid in w["loop"]:
                    if eid == -1: pass
                    else:
                        st = edges[eid][2]
                        loopstates.append(st)
                if any(done[s] for s in loopstates): errs.append("loop visits done state")
                if set(loopstates) != set([e2] if len(loopstates)==1 else loopstates):
                    pass
                # fairness conditions on the loop
                Vset = set(loopstates)
                for (a, mode) in fair:
                    enset = [x for x in Vset if a in en[x]]
                    loopedges = [eid for eid in w["loop"] if eid != -1 and edges[eid][1] == a]
                    if mode == "strong":
                        if enset and not loopedges:
                            errs.append("strong fairness %s violated" % a)
                    else:
                        if len(enset) == len(Vset) and not loopedges:
                            errs.append("weak fairness %s violated" % a)
    return errs
