"""Structural checker for the exported TLA+ module (restricted grammar)."""
import re

def parse_module(mod, n_expected, start, edges, fair, safe, done):
    errs = []
    # header / footer
    lines = mod.split("\n")
    txt = mod
    if not txt.startswith("---- MODULE ModelData ----"):
        errs.append("missing module header: %r" % txt[:40])
    if not txt.rstrip().endswith("===="):
        errs.append("missing module footer")
    # collect definitions
    body = txt[len("---- MODULE ModelData ----"):]
    body = body[:body.rfind("====")]
    # remove extends line
    m = re.search(r"EXTENDS\s+Integers\s*,\s*Sequences\s*,\s*FiniteSets", body)
    if not m:
        errs.append("EXTENDS line missing/malformed")
        return errs, None
    body = body[:m.start()] + body[m.end():]
    defs = []
    for part in re.split(r";", body):
        p = part.strip()
        if not p:
            continue
        mm = re.match(r"\A([A-Za-z][A-Za-z0-9_]*)\s*==\s*(.*)\Z", p, re.S)
        if not mm:
            errs.append("unparsable definition: %r" % p[:60])
            continue
        defs.append((mm.group(1), mm.group(2).strip()))
    if errs:
        return errs, None
    want = ["Nodes","Initial","Edges","ActionNames","WFIds","SFIds","SafeNodes","DoneNodes"]
    if [d[0] for d in defs] != want:
        errs.append("definition order/set: %s" % [d[0] for d in defs])
        return errs, None
    names = sorted(set([e[1] for e in edges] + [f[0] for f in fair]))
    idx = {nm: i+1 for i, nm in enumerate(names)}

    def parse_set(s, kind):
        """kind='int' -> set of ints; 'tuple' -> set of tuples of ints"""
        s = s.strip()
        if s == "{}":
            return set()
        if not (s.startswith("{") and s.endswith("}")):
            errs.append("bad set syntax: %r" % s[:50]); return None
        inner = s[1:-1].strip()
        if not inner:
            return set()
        items = [x.strip() for x in inner.split(",")]
        out = set()
        for it in items:
            if kind == "int":
                if not re.match(r"\A-?\d+\Z", it):
                    errs.append("bad int %r" % it); return None
                out.add(int(it))
            else:
                mm2 = re.match(r"\A<<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>>\Z", it)
                if not mm2:
                    errs.append("bad tuple %r" % it); return None
                out.add(tuple(int(g) for g in mm2.groups()))
        return out

    d = dict(defs)
    # Nodes
    if not re.match(r"\ANodes\s*==\s*0\s*\.\.\s*%d\Z" % (n_expected - 1), d["Nodes"]):
        errs.append("Nodes malformed: %r" % d["Nodes"])
    if not re.match(r"\AInitial\s*==\s*%d\Z" % start, d["Initial"]):
        errs.append("Initial malformed: %r" % d["Initial"])
    E = parse_set(d["Edges"], "tuple")
    if E is None: return errs, None
    if E != set((u, idx[nm], v) for (u, nm, v) in edges):
        errs.append("Edges mismatch: got %r" % (E,))
    # ActionNames
    an = d["ActionNames"].strip()
    if an == "<<>>":
        anames = []
    else:
        mm2 = re.match(r"\A<<(.*)>>\Z", an, re.S)
        if not mm2:
            errs.append("ActionNames malformed: %r" % an[:50]); return errs, None
        inner = mm2.group(1).strip()
        anames = [x.strip() for x in inner.split(",")] if inner else []
        for x in anames:
            if not (re.match(r'\A"[A-Za-z]([A-Za-z0-9_]*)"\Z', x)):
                errs.append("bad name literal %r" % x)
    if anames != names:
        errs.append("ActionNames mismatch: %r vs %r" % (anames, names))
    WF = parse_set(d["WFIds"], "int")
    SF = parse_set(d["SFIds"], "int")
    exp_wf = set(idx[f[0]] for f in fair if f[1] == "weak")
    exp_sf = set(idx[f[0]] for f in fair if f[1] == "strong")
    if WF != exp_wf: errs.append("WFIds mismatch %r vs %r" % (WF, exp_wf))
    if SF != exp_sf: errs.append("SFIds mismatch %r vs %r" % (SF, exp_sf))
    SN = parse_set(d["SafeNodes"], "int")
    DN = parse_set(d["DoneNodes"], "int")
    exp_sn = set(i for i in range(n_expected) if safe[i])
    exp_dn = set(i for i in range(n_expected) if done[i])
    if SN != exp_sn: errs.append("SafeNodes mismatch %r vs %r" % (sorted(SN)[:20], sorted(exp_sn)[:20]))
    if DN != exp_dn: errs.append("DoneNodes mismatch %r vs %r" % (sorted(DN)[:20], sorted(exp_dn)[:20]))
    return errs, names

def check_config(cfg):
    errs = []
    toks = ["SPECIFICATION", "Spec", "INVARIANT", "Safety", "PROPERTY",
            "Termination", "CHECK_DEADLOCK", "FALSE"]
    got = cfg.split()
    if got != toks:
        errs.append("config tokens: %r" % got)
    return errs
PYEOF
