"""Structural checker for the exported TLA+ module (restricted grammar)."""
import re

def parse_module(mod, n_expected, start, edges, fair, safe, done):
    errs = []
    if not mod.startswith("---- MODULE ModelData ----"):
        errs.append("missing module header: %r" % mod[:40])
    if not mod.rstrip().endswith("===="):
        errs.append("missing module footer")
    body = mod[len("---- MODULE ModelData ----"):]
    r = body.rfind("====")
    body = body[:r]
    m = re.search(r"EXTENDS\s+Integers\s*,\s*Sequences\s*,\s*FiniteSets", body)
    if not m:
        errs.append("EXTENDS line missing/malformed")
        return errs, None
    body = (body[:m.start()] + body[m.end():]).strip()
    if not re.match(r"\AEXTENDS", "") and not body.lstrip().startswith("Nodes"):
        errs.append("EXTENDS must precede definitions")
    rest = body
    matches = list(re.finditer(r"(?<![A-Za-z0-9_])([A-Za-z][A-Za-z0-9_]*)\s*==", rest))
    defs = []
    for i, mm in enumerate(matches):
        nm = mm.group(1)
        startv = mm.end()
        endv = matches[i + 1].start() if i + 1 < len(matches) else len(rest)
        defs.append((nm, rest[startv:endv].strip()))
    want = ["Nodes", "Initial", "Edges", "ActionNames", "WFIds", "SFIds",
            "SafeNodes", "DoneNodes"]
    if [d[0] for d in defs] != want:
        errs.append("definition order/set mismatch: %s (body=%r)" % ([d[0] for d in defs], rest[:200]))
        return errs, None
    d = dict(defs)
    names = sorted(set([e[1] for e in edges] + [f[0] for f in fair]))
    idx = {nm: i + 1 for i, nm in enumerate(names)}

    def parse_int_set(s):
        s = s.strip()
        if s == "{}":
            return set()
        if not (s.startswith("{") and s.endswith("}")):
            errs.append("bad set syntax: %r" % s[:60]); return None
        inner = s[1:-1].strip()
        if not inner:
            return set()
        outs = set()
        for it in inner.split(","):
            it = it.strip()
            if not re.match(r"\A-?\d+\Z", it):
                errs.append("bad int element %r" % it); return None
            outs.add(int(it))
        return outs

    def parse_triple_set(s):
        s = s.strip()
        if s == "{}":
            return set()
        if not (s.startswith("{") and s.endswith("}")):
            errs.append("bad set syntax: %r" % s[:60]); return None
        inner = s[1:-1].strip()
        if not inner:
            return set()
        found = list(re.finditer(r"<<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>>", inner))
        if len(found) == 0:
            errs.append("no tuples in nonempty Edges: %r" % inner[:60]); return None
        leftover = inner
        for f in reversed(found):
            leftover = leftover[:f.start()] + leftover[f.end():]
        if re.sub(r"[,\s]", "", leftover) != "":
            errs.append("leftover junk in Edges: %r" % leftover[:60]); return None
        return set(tuple(int(g) for g in f.groups()) for f in found)

    if not re.match(r"\A0\s*\.\.\s*%d\Z" % (n_expected - 1), d["Nodes"]):
        errs.append("Nodes malformed: %r" % d["Nodes"])
    if not re.match(r"\A%d\Z" % start, d["Initial"]):
        errs.append("Initial malformed: %r" % d["Initial"])
    E = parse_triple_set(d["Edges"])
    if E is None:
        return errs, None
    if E != set((u, idx[nm], v) for (u, nm, v) in edges):
        errs.append("Edges mismatch")
    an = d["ActionNames"].strip()
    if an == "<<>>":
        anames = []
    else:
        mm2 = re.match(r"\A<<(.*)>>\Z", an, re.S)
        if not mm2:
            errs.append("ActionNames malformed: %r" % an[:60]); return errs, None
        inner = mm2.group(1).strip()
        anames = [x.strip() for x in inner.split(",")] if inner else []
        for x in anames:
            if not re.match(r'\A"[A-Za-z][A-Za-z0-9_]*"\Z', x):
                errs.append("bad name literal %r" % x)
    if anames != names:
        errs.append("ActionNames mismatch: %r vs %r" % (anames, names))
    WF = parse_int_set(d["WFIds"])
    SF = parse_int_set(d["SFIds"])
    exp_wf = set(idx[f[0]] for f in fair if f[1] == "weak")
    exp_sf = set(idx[f[0]] for f in fair if f[1] == "strong")
    if WF != exp_wf: errs.append("WFIds mismatch %r vs %r" % (WF, exp_wf))
    if SF != exp_sf: errs.append("SFIds mismatch %r vs %r" % (SF, exp_sf))
    SN = parse_int_set(d["SafeNodes"])
    DN = parse_int_set(d["DoneNodes"])
    exp_sn = set(i for i in range(n_expected) if safe[i])
    exp_dn = set(i for i in range(n_expected) if done[i])
    if SN != exp_sn: errs.append("SafeNodes mismatch")
    if DN != exp_dn: errs.append("DoneNodes mismatch")
    return errs, names

