    R = len(v[0])
    if R > 128:
        raise LimitErr()
    for row in v:
        if len(row) != R:
            raise SchemaErr()
    if R == 0:
        return P, 0, 0, v
    first = v[0][0]
    if type(first) is not list:
        raise SchemaErr()
    D = len(first)
