def compute_sccs(n, adj, active):
    """Iterative Tarjan decomposition of the subgraph induced by active."""
    idx = [-1] * n
    low = [0] * n
    onstk = bytearray(n)
    sstack = []
    comps = []
    cnt = 0
    for root in range(n):
        if not active[root] or idx[root] != -1:
            continue
        idx[root] = low[root] = cnt
        cnt += 1
        sstack.append(root)
        onstk[root] = 1
        fnode = [root]
        fptr = [0]
        while fnode:
            v = fnode[-1]
            av = adj[v]
            la = len(av)
            pi = fptr[-1]
            advanced = False
            while pi < la:
                w = av[pi]
                pi += 1
                if not active[w]:
                    continue
                iw = idx[w]
                if iw == -1:
                    fptr[-1] = pi
                    idx[w] = low[w] = cnt
                    cnt += 1
                    sstack.append(w)
                    onstk[w] = 1
                    fnode.append(w)
                    fptr.append(0)
                    advanced = True
                    break
                elif onstk[w]:
                    if iw < low[v]:
                        low[v] = iw
            if advanced:
                continue
            fnode.pop()
            fptr.pop()
            lv = low[v]
            if fnode:
                p = fnode[-1]
                if lv < low[p]:
                    low[p] = lv
            if lv == idx[v]:
                comp = []
                while True:
                    w = sstack.pop()
                    onstk[w] = 0
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)
    return comps


