def process_line(line):
    if len(line) > LINE_MAX:
        return '{"error":"E_LIMIT"}'
    try:
        text = line.decode('utf-8')
    except UnicodeDecodeError:
        return '{"error":"E_JSON"}'
    try:
        obj = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_bad_const, parse_float=_parse_float)
    except JsonErr:
        return '{"error":"E_JSON"}'
    except (ValueError, RecursionError):
        return '{"error":"E_JSON"}'
    try:
        res = handle(obj)
    except LimitErr:
        return '{"error":"E_LIMIT"}'
    except SchemaErr:
        return '{"error":"E_SCHEMA"}'
    except Exception:
        return '{"error":"E_SCHEMA"}'
    try:
        return json.dumps(res)
    except Exception:
        return '{"error":"E_SCHEMA"}'


def main():
    data = sys.stdin.buffer.read()
    out = sys.stdout.write
    pos = 0
    n = len(data)
    while pos < n:
        i = data.find(b'\n', pos)
        if i < 0:
            line = data[pos:]
            pos = n
        else:
            line = data[pos:i]
            pos = i + 1
        out(process_line(line))
        out('\n')
    sys.stdout.flush()


